import React from 'react';
import { Box, Grid, Paper, Stack, Typography } from '@mui/material';
import { formatCo2eFromKg } from '../../constants/carbonVisualization';

export type DriverKgRow = { label: string; kg: number };
export type DriverShareRow = { label: string; percent: number };

export type AnalyticsDriversBoardProps = {
  hotspots: DriverKgRow[];
  sectorFocus: DriverKgRow[];
  applicationCategories: DriverKgRow[];
  vendors: DriverKgRow[];
  valueChain: DriverShareRow[];
};

const KgBars = ({ rows }: { rows: DriverKgRow[] }) => {
  const visible = rows.filter((row) => row.label && row.kg > 0).slice(0, 8);
  const max = Math.max(...visible.map((row) => row.kg), 0);
  if (visible.length === 0) {
    return <Typography variant="body2" color="text.secondary">No rows in this inventory yet.</Typography>;
  }
  const unit: 'kg' | 't' = visible.some((row) => row.kg >= 1000) ? 't' : 'kg';
  return (
    <Stack spacing={1}>
      {visible.map((row) => (
        <Box key={row.label}>
          <Stack direction="row" justifyContent="space-between" spacing={1}>
            <Typography variant="body2" sx={{ fontWeight: 700 }}>{row.label}</Typography>
            <Typography variant="caption" color="text.secondary">{formatCo2eFromKg(row.kg, { unit })}</Typography>
          </Stack>
          <Box sx={{ mt: 0.4, height: 8, borderRadius: 99, bgcolor: 'action.hover' }}>
            <Box sx={{ width: `${Math.max(8, (row.kg / max) * 100)}%`, height: '100%', borderRadius: 99, bgcolor: '#0f766e' }} />
          </Box>
        </Box>
      ))}
    </Stack>
  );
};

const ShareBars = ({ rows }: { rows: DriverShareRow[] }) => {
  const visible = rows.filter((row) => row.label && row.percent > 0).slice(0, 8);
  if (visible.length === 0) {
    return <Typography variant="body2" color="text.secondary">No rows in this inventory yet.</Typography>;
  }
  return (
    <Stack spacing={1}>
      {visible.map((row) => (
        <Box key={row.label}>
          <Stack direction="row" justifyContent="space-between" spacing={1}>
            <Typography variant="body2" sx={{ fontWeight: 700 }}>{row.label}</Typography>
            <Typography variant="caption" color="text.secondary">{`${Math.round(row.percent)}%`}</Typography>
          </Stack>
          <Box sx={{ mt: 0.4, height: 8, borderRadius: 99, bgcolor: 'action.hover' }}>
            <Box sx={{ width: `${Math.max(8, Math.min(100, row.percent))}%`, height: '100%', borderRadius: 99, bgcolor: '#7c3aed' }} />
          </Box>
        </Box>
      ))}
    </Stack>
  );
};

const sections: Array<{ title: string; note: string; key: keyof AnalyticsDriversBoardProps }> = [
  { key: 'hotspots', title: 'Hotspots', note: 'Highest-impact sources in this inventory.' },
  { key: 'sectorFocus', title: 'Sector focus', note: 'Categories this sector is expected to watch.' },
  { key: 'applicationCategories', title: 'Largest application categories', note: 'Where the included kilograms sit.' },
  { key: 'vendors', title: 'Vendors', note: 'Suppliers and ledgers that carry the most included kilograms.' },
  { key: 'valueChain', title: 'Value chain', note: 'Share of the footprint by value-chain stage.' },
];

const AnalyticsDriversBoard: React.FC<AnalyticsDriversBoardProps> = (props) => (
  <Stack spacing={1.5} data-testid="analytics-drivers-board">
    <Typography variant="h6" sx={{ fontWeight: 800 }}>Inventory drivers</Typography>
    <Grid container spacing={1.5}>
      {sections.map((section) => (
        <Grid item xs={12} md={6} key={section.key}>
          <Paper variant="outlined" sx={{ p: 1.5, height: '100%' }}>
            <Typography variant="subtitle2" sx={{ fontWeight: 800 }}>{section.title}</Typography>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>{section.note}</Typography>
            {section.key === 'valueChain'
              ? <ShareBars rows={props.valueChain} />
              : <KgBars rows={props[section.key] as DriverKgRow[]} />}
          </Paper>
        </Grid>
      ))}
    </Grid>
  </Stack>
);

export default AnalyticsDriversBoard;
