import React, { useMemo } from 'react';
import { Box, Grid, Paper, Stack, Typography } from '@mui/material';
import { formatCo2eFromKg } from '../../constants/carbonVisualization';

export type ActivityVisualRow = {
  category?: string;
  kg: number;
};

export type ActivityPeriodBar = {
  label: string;
  emissions: number;
};

export type ActivityVisualSummaryProps = {
  rows: ActivityVisualRow[];
  periods: ActivityPeriodBar[];
};

const humanize = (value: string): string => {
  const words = value.replace(/[_-]+/g, ' ').trim();
  if (!words) return 'Other';
  return words.charAt(0).toUpperCase() + words.slice(1);
};

const ActivityVisualSummary: React.FC<ActivityVisualSummaryProps> = ({ rows, periods }) => {
  const categoryBars = useMemo(() => {
    const totals = new Map<string, number>();
    rows.forEach((row) => {
      const kg = Math.max(0, Number(row.kg) || 0);
      if (kg <= 0) return;
      const key = humanize(row.category || 'Other');
      totals.set(key, (totals.get(key) || 0) + kg);
    });
    return Array.from(totals.entries())
      .map(([label, kg]) => ({ label, kg }))
      .sort((a, b) => b.kg - a.kg)
      .slice(0, 6);
  }, [rows]);

  const totalKg = categoryBars.reduce((sum, row) => sum + row.kg, 0);
  const maxCategory = Math.max(...categoryBars.map((row) => row.kg), 0);
  const visiblePeriods = periods.filter((period) => period.emissions > 0).slice(-8);
  const maxPeriod = Math.max(...visiblePeriods.map((period) => period.emissions), 0);
  const unit: 'kg' | 't' = totalKg >= 1000 ? 't' : 'kg';

  if (categoryBars.length === 0 && visiblePeriods.length === 0) {
    return null;
  }

  return (
    <Grid container spacing={1.5} sx={{ mb: 2 }} data-testid="activity-visual-summary">
      <Grid item xs={12} md={visiblePeriods.length > 0 ? 7 : 12}>
        <Paper variant="outlined" sx={{ p: 1.5, height: '100%' }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 800, mb: 1 }}>
            {totalKg > 0 ? `Where the ${formatCo2eFromKg(totalKg, { unit })} comes from` : 'Activity mix'}
          </Typography>
          <Stack spacing={1}>
            {categoryBars.map((row) => (
              <Box key={row.label}>
                <Stack direction="row" justifyContent="space-between" spacing={1}>
                  <Typography variant="body2" sx={{ fontWeight: 700 }}>{row.label}</Typography>
                  <Typography variant="caption" color="text.secondary">
                    {formatCo2eFromKg(row.kg, { unit })}
                  </Typography>
                </Stack>
                <Box sx={{ mt: 0.4, height: 8, borderRadius: 99, bgcolor: 'action.hover' }}>
                  <Box
                    sx={{
                      width: `${maxCategory > 0 ? Math.max(8, (row.kg / maxCategory) * 100) : 0}%`,
                      height: '100%',
                      borderRadius: 99,
                      bgcolor: '#0f766e',
                    }}
                  />
                </Box>
              </Box>
            ))}
          </Stack>
        </Paper>
      </Grid>
      {visiblePeriods.length > 0 ? (
        <Grid item xs={12} md={5}>
          <Paper variant="outlined" sx={{ p: 1.5, height: '100%' }}>
            <Typography variant="subtitle2" sx={{ fontWeight: 800, mb: 1 }}>
              Emissions by period
            </Typography>
            <Stack direction="row" spacing={0.75} alignItems="flex-end" sx={{ height: 140 }}>
              {visiblePeriods.map((period) => (
                <Box key={period.label} sx={{ flex: 1, minWidth: 0, textAlign: 'center' }}>
                  <Box
                    sx={{
                      height: `${maxPeriod > 0 ? Math.max(8, (period.emissions / maxPeriod) * 112) : 8}px`,
                      borderRadius: 1,
                      bgcolor: '#2563eb',
                      mx: 'auto',
                      width: '70%',
                    }}
                    title={formatCo2eFromKg(period.emissions)}
                  />
                  <Typography variant="caption" color="text.secondary" display="block" noWrap sx={{ mt: 0.5 }}>
                    {period.label}
                  </Typography>
                </Box>
              ))}
            </Stack>
          </Paper>
        </Grid>
      ) : null}
    </Grid>
  );
};

export default ActivityVisualSummary;
